import java.util.*;

public class MinCostMaxFlow {
    static final int INF = 0x3f3f3f3f;
    static int[] px = new int[10000], py = new int[10000];
    static int[] head = new int[10000], to = new int[100000], ct = new int[100000], w = new int[100000], nt = new int[100000];
