    static int source, sink, edgeCount;

    static void addEdge(int u, int v, int flow, int cost) {
        to[edgeCount] = v; ct[edgeCount] = cost; w[edgeCount] = flow; nt[edgeCount] = head[u]; head[u] = edgeCount++;
        to[edgeCount] = u; ct[edgeCount] = -cost; w[edgeCount] = 0; nt[edgeCount] = head[v]; head[v] = edgeCount++;
    }

    static void initGraph() {
        Arrays.fill(head, -1);
        edgeCount = 0;
    }

    static boolean spfa(int s, int t) {
        Arrays.fill(dist, INF);
        Arrays.fill(inQueue, 0);
        Arrays.fill(parent, -1);
        dist[s] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(s);
        while (!q.isEmpty()) {
            int u = q.poll();
            inQueue[u] = 0;
            for (int i = head[u]; i != -1; i = nt[i]) {
                if (w[i] > 0 && dist[to[i]] > dist[u] + ct[i]) {
                    dist[to[i]] = dist[u] + ct[i];
                    parent[to[i]] = u;
                    edgeId[to[i]] = i;
                    if (inQueue[to[i]] == 0) {
                        inQueue[to[i]] = 1;
                        q.offer(to[i]);
                    }
                }
            }
        }
        return dist[t] < INF;
    }

    static int minCostMaxFlow(int s, int t) {
        int totalCost = 0, totalFlow = 0;
        while (spfa(s, t)) {
            int flowAmount = INF;
            for (int i = t; i != s; i = parent[i]) {
